namespace AfterDarkClassic {
 static class SetupProgram {
  public const string UninstallKey=@"Software\Microsoft\Windows\CurrentVersion\Uninstall\AfterDarkClassic";
  [STAThread] static void Main(string[] args){try{
   if(args.Length>1 && args[0]=="/apply"){if(!new WindowsPrincipal(WindowsIdentity.GetCurrent()).IsInRole(WindowsBuiltInRole.Administrator))throw new InvalidOperationException("La instalación necesita permisos de administrador.");Install(args[1],args.Length>2?args[2]:"all");return;}
   if(args.Length>0 && args[0]=="/uninstall"){if(MessageBox.Show("¿Desinstalar After Dark Classic?\r\nSe conservarán los ajustes y las copias de seguridad.","After Dark",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;BeginRemove();return;}
   if(args.Length>1 && args[0]=="/render"){int page=args.Length>2?int.Parse(args[2]):0;UI.Render(new Wizard(page),args[1]);return;}
   if(args.Length>0 && args[0]=="/check-payload"){using(var z=new ZipArchive(Assembly.GetExecutingAssembly().GetManifestResourceStream("payload.zip"),ZipArchiveMode.Read)){int n=0;foreach(var e in z.Entries){using(var stream=e.Open()){byte[] b=new byte[8192];while(stream.Read(b,0,b.Length)>0){}}n++;}File.WriteAllText(args[1],"Payload entries read successfully: "+n);}return;}
   if(args.Length>1 && args[0]=="/extract-test"){string folder=Path.GetFullPath(args[1]);if(Directory.Exists(folder)&&Directory.GetFileSystemEntries(folder).Length>0)throw new IOException("Test directory must be empty.");Directory.CreateDirectory(folder);var d=new XmlDocument();var root=d.CreateElement("test");d.AppendChild(root);ExtractPayload(folder,d,root);return;}
   if(args.Length>1&&args[0]=="/files-test"){PackageFiles.SelfTest(args[1]);return;}
   if(args.Length>2&&args[0]=="/remove-from"){RemoveFrom(args[1],int.Parse(args[2]));return;}
   Application.Run(new Backdrop());
  }catch(Exception ex){if(args.Length>1&&(args[0].EndsWith("test")||args[0]=="/render"))File.WriteAllText(args[1]+".error.txt",ex.ToString());else UI.Error(ex);Environment.ExitCode=1;}}
  static void SaveValue(XmlDocument doc,XmlElement root,string scope,string key,string name){RegistryKey baseKey=scope=="machine"?Registry.LocalMachine:Registry.CurrentUser;using(var k=baseKey.OpenSubKey(key)){var e=doc.CreateElement("registry");e.SetAttribute("scope",scope);e.SetAttribute("key",key);e.SetAttribute("name",name);object value=k==null?null:k.GetValue(name,null);e.SetAttribute("exists",value==null?"0":"1");if(value!=null){e.SetAttribute("kind",k.GetValueKind(name).ToString());e.InnerText=Convert.ToString(value); }root.AppendChild(e);}}
  static void ExtractPayload(string folder,XmlDocument doc,XmlElement root){using(var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("payload.zip"))using(var zip=new ZipArchive(stream,ZipArchiveMode.Read)){foreach(var entry in zip.Entries){string dest=Path.GetFullPath(Path.Combine(folder,entry.FullName));if(!dest.StartsWith(folder+"\\",StringComparison.OrdinalIgnoreCase))throw new IOException("Ruta inválida en el paquete.");if(string.IsNullOrEmpty(entry.Name)){Directory.CreateDirectory(dest);continue;}Directory.CreateDirectory(Path.GetDirectoryName(dest));var f=doc.CreateElement("file");f.SetAttribute("path",entry.FullName);root.AppendChild(f);entry.ExtractToFile(dest);}}}
  public static string RegisteredFolder(){using(var key=Registry.LocalMachine.OpenSubKey(UninstallKey))return key==null?"":Convert.ToString(key.GetValue("InstallLocation",""));}
  static void EnsureClosed(string folder){foreach(string name in new[]{"AfterDarkControl","After Dark","After Dark Engine"})foreach(var p in Process.GetProcessesByName(name)){try{if(string.Equals(Path.GetDirectoryName(p.MainModule.FileName),folder,StringComparison.OrdinalIgnoreCase))throw new IOException("Elegí Salir desde el icono de After Dark junto al reloj y cerrá las vistas previas antes de continuar.");}finally{p.Dispose();}}}
  static XmlDocument CaptureSystem(){var d=new XmlDocument();var r=d.CreateElement("installation");d.AppendChild(r);SaveValue(d,r,"machine",Paths.Machine,"Path");SaveValue(d,r,"machine",Paths.Machine,"Installed");SaveValue(d,r,"machine",@"Software\Microsoft\Windows\CurrentVersion\Run","After Dark QuickAccess");foreach(string name in new[]{"DisplayName","DisplayVersion","InstallLocation","DisplayIcon","UninstallString","NoModify","NoRepair"})SaveValue(d,r,"machine",UninstallKey,name);string winIni=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows),"win.ini");foreach(string name in new[]{"After Dark","AD INI Files","AD Data Files"}){var e=d.CreateElement("ini");e.SetAttribute("key",name);e.InnerText=Native.IniRead("Berkeley Systems",name,"",winIni);r.AppendChild(e);}return d;}
  static void Install(string folder,string selection){folder=PackageFiles.ValidateRoot(folder);string registered=RegisteredFolder();if(registered.Length>0&&!string.Equals(Path.GetFullPath(registered).TrimEnd('\\'),folder,StringComparison.OrdinalIgnoreCase))throw new IOException("Para actualizar, elegí la carpeta de la instalación existente: "+registered);EnsureClosed(folder);
   string manifest=Path.Combine(folder,"installation.xml");var rollback=CaptureSystem();XmlDocument doc;
   var previous=new System.Collections.Generic.List<string>();if(File.Exists(manifest)){doc=new XmlDocument();doc.Load(manifest);if(!string.Equals(Path.GetFullPath(doc.DocumentElement.GetAttribute("root")).TrimEnd('\\'),folder,StringComparison.OrdinalIgnoreCase))throw new IOException("El registro de instalación no corresponde a esta carpeta.");foreach(XmlElement e in doc.SelectNodes("/installation/file"))previous.Add(e.GetAttribute("path"));foreach(XmlNode n in doc.SelectNodes("/installation/file"))n.ParentNode.RemoveChild(n);}else doc=CaptureSystem();var root=doc.DocumentElement;root.SetAttribute("root",folder);
   string stage=Path.Combine(Path.GetTempPath(),"AfterDark-Stage-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(stage);try{var staging=new XmlDocument();staging.AppendChild(staging.CreateElement("stage"));ExtractPayload(stage,staging,staging.DocumentElement);
    if(selection!="all"){var catalog=new XmlDocument();catalog.Load(Path.Combine(stage,"catalog.xml"));var included=new System.Collections.Generic.List<string>();var ids=new System.Collections.Generic.HashSet<string>(selection.Split(','));int i=0;foreach(XmlElement e in catalog.SelectNodes("/catalog/module")){if(ids.Contains((i++).ToString()))included.Add(e.GetAttribute("name"));else File.Delete(Path.Combine(stage,"After Dark 4.0",e.GetAttribute("file")));}if(included.Count==0)throw new IOException("Seleccioná al menos un salvapantallas.");File.WriteAllLines(Path.Combine(stage,"installed-modules.txt"),included);}
    File.Copy(Application.ExecutablePath,Path.Combine(stage,"Desinstalar.exe"));var files=new System.Collections.Generic.HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(string f in Directory.GetFiles(stage,"*",SearchOption.AllDirectories)){string relative=f.Substring(stage.Length+1);files.Add(relative);var e=doc.CreateElement("file");e.SetAttribute("path",relative);root.AppendChild(e);}
    using(var transaction=new PackageFiles(folder)){bool complete=false;try{foreach(string f in files)transaction.Put(f,Path.Combine(stage,f));foreach(string f in previous)if(!files.Contains(f))transaction.Delete(f);
      Directory.CreateDirectory(Paths.Data);var info=new DirectoryInfo(Paths.Data);var acl=info.GetAccessControl();acl.AddAccessRule(new FileSystemAccessRule(new SecurityIdentifier(WellKnownSidType.BuiltinUsersSid,null),FileSystemRights.Modify,InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit,PropagationFlags.None,AccessControlType.Allow));info.SetAccessControl(acl);
      string winIni=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows),"win.ini"),oldIni=Native.IniRead("Berkeley Systems","AD INI Files","",winIni),existing=Path.Combine(oldIni,"modules.ini");if(!File.Exists(Paths.Ini)&&File.Exists(existing))File.Copy(existing,Paths.Ini);
      using(var k=Registry.LocalMachine.CreateSubKey(Paths.Machine)){k.SetValue("Path",folder);k.SetValue("Installed","Yes");}Native.IniWrite("Berkeley Systems","After Dark",folder,winIni);Native.IniWrite("Berkeley Systems","AD INI Files",Paths.Data,winIni);Native.IniWrite("Berkeley Systems","AD Data Files",folder,winIni);using(var k=Registry.LocalMachine.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Run",true)){if(k!=null)k.DeleteValue("After Dark QuickAccess",false);}
      using(var k=Registry.LocalMachine.CreateSubKey(UninstallKey)){k.SetValue("DisplayName","After Dark Classic — panel compatible");k.SetValue("DisplayVersion","0.5");k.SetValue("InstallLocation",folder);k.SetValue("DisplayIcon",Path.Combine(folder,"Assets","AfterDark.ico"));k.SetValue("UninstallString",Paths.Quote(Path.Combine(folder,"Desinstalar.exe"))+" /uninstall");k.SetValue("NoModify",1,RegistryValueKind.DWord);k.SetValue("NoRepair",1,RegistryValueKind.DWord);}
      string generated=Path.Combine(stage,"installation.xml");doc.Save(generated);transaction.Put("installation.xml",generated);transaction.Commit();complete=true;
     }finally{if(!complete)Restore(rollback.DocumentElement);}}
   }finally{PackageFiles.CleanScratch(stage);}
  }

  static void Restore(XmlElement root){foreach(XmlElement e in root.SelectNodes("registry")){var baseKey=e.GetAttribute("scope")=="machine"?Registry.LocalMachine:Registry.CurrentUser;using(var k=baseKey.CreateSubKey(e.GetAttribute("key"))){if(e.GetAttribute("exists")=="0")k.DeleteValue(e.GetAttribute("name"),false);else{RegistryValueKind kind=(RegistryValueKind)Enum.Parse(typeof(RegistryValueKind),e.GetAttribute("kind"));k.SetValue(e.GetAttribute("name"),kind==RegistryValueKind.DWord?(object)int.Parse(e.InnerText):e.InnerText,kind);}}}string winIni=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows),"win.ini");foreach(XmlElement e in root.SelectNodes("ini"))Native.IniWrite("Berkeley Systems",e.GetAttribute("key"),e.InnerText.Length==0?null:e.InnerText,winIni);}
  static void BeginRemove(){string root=PackageFiles.ValidateRoot(Paths.Root);EnsureClosed(root);string registered=RegisteredFolder();if(registered.Length>0&&!string.Equals(Path.GetFullPath(registered).TrimEnd('\\'),root,StringComparison.OrdinalIgnoreCase))throw new IOException("Este desinstalador pertenece a otra instalación.");string temporary=Path.Combine(Path.GetTempPath(),"AfterDark-Uninstall-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(temporary);string helper=Path.Combine(temporary,"Desinstalar.exe");File.Copy(Application.ExecutablePath,helper);Process.Start(new ProcessStartInfo(helper,"/remove-from "+Paths.Quote(root)+" "+Process.GetCurrentProcess().Id){UseShellExecute=true,Verb="runas"});WindowsSaver.Restore(root);}
  static void RemoveFrom(string folder,int parent){if(!new WindowsPrincipal(WindowsIdentity.GetCurrent()).IsInRole(WindowsBuiltInRole.Administrator))throw new IOException("La desinstalación necesita permisos.");try{using(var p=Process.GetProcessById(parent)){if(!p.WaitForExit(30000))throw new IOException("Cerrá el desinstalador anterior para continuar.");}}catch(ArgumentException){}Paths.Root=PackageFiles.ValidateRoot(folder);Remove();}

  static void Remove(){if(!new WindowsPrincipal(WindowsIdentity.GetCurrent()).IsInRole(WindowsBuiltInRole.Administrator)){var p=Process.Start(new ProcessStartInfo(Application.ExecutablePath,"/uninstall"){UseShellExecute=true,Verb="runas"});p.WaitForExit();if(p.ExitCode==0)WindowsSaver.Restore(Paths.Root);p.Dispose();return;}string folder=Paths.Root;string manifest=Path.Combine(folder,"installation.xml");var doc=new XmlDocument();doc.Load(manifest);if(!string.Equals(Path.GetFullPath(doc.DocumentElement.GetAttribute("root")),Path.GetFullPath(folder),StringComparison.OrdinalIgnoreCase))throw new IOException("La carpeta no coincide con el registro de instalación.");foreach(var p in Process.GetProcessesByName("AfterDarkControl")){try{if(string.Equals(p.MainModule.FileName,Path.Combine(folder,"AfterDarkControl.exe"),StringComparison.OrdinalIgnoreCase))throw new IOException("Cerrá After Dark desde su icono junto al reloj antes de desinstalar.");}finally{p.Dispose();}}
   WindowsSaver.Restore(folder);Restore(doc.DocumentElement);Registry.LocalMachine.DeleteSubKeyTree(UninstallKey,false);using(var k=Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Run",true)){if(k!=null && Convert.ToString(k.GetValue("AfterDarkClassic","")).IndexOf(folder,StringComparison.OrdinalIgnoreCase)>=0)k.DeleteValue("AfterDarkClassic",false);}
   foreach(XmlElement e in doc.SelectNodes("/installation/file")){string dest=PackageFiles.Inside(folder,e.GetAttribute("path"));if(string.Equals(dest,Application.ExecutablePath,StringComparison.OrdinalIgnoreCase))continue;if(File.Exists(dest))File.Delete(dest);}File.Delete(manifest);foreach(string oldBackup in Directory.GetFiles(folder,"AfterDarkControl.backup-*.bak")){string safe=PackageFiles.Inside(folder,Path.GetFileName(oldBackup));string saved=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData),"AfterDarkClassic","ProgramBackups");Directory.CreateDirectory(saved);File.Copy(safe,Path.Combine(saved,Guid.NewGuid().ToString("N")+"-"+Path.GetFileName(safe)));File.Delete(safe);}PackageFiles.Prune(folder,true);MessageBox.Show("After Dark Classic se desinstaló. Se conservaron los ajustes y los archivos ajenos al programa.","After Dark");
  }
 }
 class Backdrop:Form {
  public Backdrop(){Text="After Dark 4.0 Setup";WindowState=FormWindowState.Maximized;BackColor=Color.Blue;Shown+=(s,e)=>{using(var wizard=new Wizard(0)){wizard.ShowDialog(this);}Close();};}
  protected override void OnPaintBackground(PaintEventArgs e){using(var brush=new LinearGradientBrush(ClientRectangle,Color.Blue,Color.Black,LinearGradientMode.Vertical))e.Graphics.FillRectangle(brush,ClientRectangle);}
 }
 class Wizard:Form {
  int page;PictureBox art;Panel content;Button back,next,cancel;string target=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86),"After Dark Classic 0.5");TextBox folder;RadioButton custom;bool customMode;bool launch=true;CheckBox launchBox;CheckedListBox moduleList;bool[] selected=new bool[24];bool installing;bool updating;
  public Wizard(int initial){for(int i=0;i<selected.Length;i++)selected[i]=true;page=initial;Text="After Dark 4.0 — Instalación";Font=UI.Font;Icon=GetSetupIcon();ClientSize=new Size(429,294);FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;MinimizeBox=false;StartPosition=FormStartPosition.CenterScreen;AutoScaleMode=AutoScaleMode.Dpi;BackColor=SystemColors.Control;art=new PictureBox{Bounds=new Rectangle(10,10,119,226),SizeMode=PictureBoxSizeMode.StretchImage,BackColor=Color.Black};Controls.Add(art);content=new Panel{Bounds=new Rectangle(148,10,270,226)};Controls.Add(content);var line=new Label{BorderStyle=BorderStyle.Fixed3D,Bounds=new Rectangle(10,248,409,2)};Controls.Add(line);back=UI.Button(this,"< Atrás",190,263,74,(s,e)=>{CaptureState();page--;if(page==3&&!customMode)page--;Draw();});next=UI.Button(this,"Siguiente >",264,263,74,(s,e)=>Advance());cancel=UI.Button(this,"Cancelar",344,263,74,(s,e)=>Close());back.Height=next.Height=cancel.Height=23;FormClosing+=(s,e)=>{if(installing)e.Cancel=true;};string installed=SetupProgram.RegisteredFolder();if(installed.Length>0){target=installed;updating=true;}Draw();}
  Icon GetSetupIcon(){using(var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("setup.ico"))return new Icon(stream);}
  Image PageImage(int n){using(var s=Assembly.GetExecutingAssembly().GetManifestResourceStream("page"+n+".bmp"))return new Bitmap(Image.FromStream(s));}
  void CaptureState(){if(page==1 && folder!=null)target=folder.Text.Trim();if(page==2 && custom!=null)customMode=custom.Checked;if(page==5&&launchBox!=null)launch=launchBox.Checked;if(page==3&&moduleList!=null)for(int i=0;i<24;i++)selected[i]=moduleList.GetItemChecked(i);}
  void Draw(){while(content.Controls.Count>0)content.Controls[0].Dispose();var old=art.Image;art.Image=PageImage(page==0?1:page==1?3:page==2?4:page==3?5:page==4?6:1);if(old!=null)old.Dispose();back.Enabled=page>0&&page<5;next.Text=page==4?"Instalar":page==5?"Finalizar":"Siguiente >";cancel.Visible=page<5;
   if(page==0){Text="After Dark 4.0 — Bienvenido";UI.Label(content,"Bienvenido al asistente de instalación de After Dark.",0,0,270,36);UI.Label(content,"Este asistente instalará los salvapantallas originales y el nuevo panel de control compatible.",0,53,270,48);UI.Label(content,"Los próximos pasos son:\r\n\r\n1) Elegir la carpeta de destino.\r\n2) Copiar los archivos.\r\n3) Configurar After Dark.",0,117,270,108);}
   if(page==1){Text="After Dark 4.0 — Carpeta de destino";UI.Label(content,"Elegí dónde instalar After Dark Classic.\r\nPodés actualizar la instalación existente. Tus ajustes se conservarán.",0,0,270,60);var group=new GroupBox{Text="Carpeta de destino",Bounds=new Rectangle(0,105,270,65)};content.Controls.Add(group);folder=new TextBox{Bounds=new Rectangle(8,25,175,23),Text=target};group.Controls.Add(folder);UI.Button(group,"Buscar…",188,25,74,(s,e)=>{using(var d=new FolderBrowserDialog{SelectedPath=target,Description="Elegí la carpeta de After Dark Classic"}){if(d.ShowDialog(this)==DialogResult.OK)folder.Text=d.SelectedPath;}});UI.Label(content,"Espacio necesario: aproximadamente 45 MB",0,188,270,28);}
   if(page==2){Text="After Dark 4.0 — Tipo de instalación";UI.Label(content,"Seleccioná el tipo de instalación:",0,0,270,30);var typical=new RadioButton{Text="Típica",Bounds=new Rectangle(0,63,96,24),Checked=!customMode};content.Controls.Add(typical);UI.Label(content,"Instala los 24 salvapantallas, el panel y el icono junto al reloj.",104,61,163,65);custom=new RadioButton{Text="Personalizada",Bounds=new Rectangle(0,145,100,24),Checked=customMode};content.Controls.Add(custom);UI.Label(content,"Permite elegir qué salvapantallas instalar.",104,143,163,65);}
   if(page==3){Text="After Dark 4.0 — Componentes";UI.Label(content,"Elegí los salvapantallas que querés instalar:",0,0,270,30);moduleList=new CheckedListBox{Bounds=new Rectangle(0,30,270,166),CheckOnClick=true};content.Controls.Add(moduleList);using(var zip=new ZipArchive(Assembly.GetExecutingAssembly().GetManifestResourceStream("payload.zip"),ZipArchiveMode.Read)){var entry=zip.GetEntry("catalog.xml");var d=new XmlDocument();using(var stream=entry.Open())d.Load(stream);int i=0;foreach(XmlElement e in d.SelectNodes("/catalog/module")){moduleList.Items.Add(e.GetAttribute("name"),selected[i++]);}}UI.Label(content,"El panel de control y el motor se instalan siempre.",0,204,270,22);}
   if(page==4){Text="After Dark 4.0 — Listo para instalar";UI.Label(content,"El asistente está listo para copiar los archivos.",0,0,270,36);UI.Label(content,"Carpeta de destino:\r\n"+target,0,54,270,62);UI.Label(content,"Se instalarán el motor original, los módulos elegidos y el nuevo panel de control.\r\n\r\nWindows solicitará permisos para completar la instalación.",0,126,270,94);}
   if(page==5){Text="After Dark 4.0 — Instalación completa";UI.Label(content,"After Dark se instaló correctamente.",0,0,270,36);UI.Label(content,"El panel permite elegir y configurar los salvapantallas. Al cerrarlo, permanece disponible junto al reloj.",0,59,270,80);launchBox=new CheckBox{Text="Abrir After Dark ahora",Bounds=new Rectangle(0,174,270,25),Checked=launch};content.Controls.Add(launchBox);}
  }
  void Advance(){CaptureState();if(page==5){if(launchBox.Checked)Process.Start(Path.Combine(target,"AfterDarkControl.exe"));Close();return;}if(page==1){try{target=Path.GetFullPath(target);if(!Path.IsPathRooted(target))throw new IOException();target=PackageFiles.ValidateRoot(target);}catch(Exception ex){UI.Error(ex);return;}}
   if(page==3 && Array.IndexOf(selected,true)<0){MessageBox.Show("Seleccioná al menos un salvapantallas.");return;}
   if(page==4){try{installing=true;next.Enabled=false;back.Enabled=false;cancel.Enabled=false;string selection="all";if(customMode){var parts=new System.Collections.Generic.List<string>();for(int i=0;i<24;i++)if(selected[i])parts.Add(i.ToString());selection=string.Join(",",parts);}var process=Process.Start(new ProcessStartInfo(Application.ExecutablePath,"/apply "+Paths.Quote(target)+" "+selection){UseShellExecute=true,Verb="runas"});while(!process.HasExited){Application.DoEvents();System.Threading.Thread.Sleep(50);}if(process.ExitCode!=0)throw new IOException("La instalación no se completó. Podés revisar la carpeta e intentar nuevamente.");process.Dispose();bool enabled=updating?Paths.Int(WindowsSaver.Desktop,"ScreenSaveActive",1)!=0:true;WindowsSaver.Configure(target,enabled,WindowsSaver.Seconds());Paths.Write(Paths.Modern,"Enabled",enabled?1:0);page=5;}catch(Exception ex){UI.Error(ex);page=4;}finally{installing=false;next.Enabled=true;cancel.Enabled=true;}Draw();return;}
   page++;if(page==3&&!customMode)page=4;Draw();
  }
 }
